import {cms} from '@/cms'
import {Author, BlogPost} from '@/schema'
import {Query} from 'alinea'

export async function authorPage(path: string) {
  return cms.get({
    type: Author,
    path,
    select: {
      name: Query.title,
      bio: Author.bio,
      // The posts whose author field links to this author
      posts: Query.referencedBy({
        type: BlogPost,
        field: BlogPost.author,
        select: {title: Query.title, url: Query.url},
        orderBy: {desc: BlogPost.publishDate}
      }),
      // Every entry linking to the author, in any field
      mentions: Query.referencedBy({count: true})
    }
  })
}

import {cms} from '@/cms'
import {Author, BlogPost} from '@/schema'
import {Query} from 'alinea'

// Authors of at least one featured post
const featuredAuthors = await cms.find({
  type: Author,
  filter: {
    _referenced: Query.referencedBy({
      type: BlogPost,
      field: BlogPost.author,
      filter: {featured: true}
    })
  },
  select: Query.title
})

import {cms} from '@/cms'
import {BlogPost} from '@/schema'
import {Query} from 'alinea'

export async function postsBy(authorId: string, page: number) {
  return cms.find({
    type: BlogPost,
    // Single link: has, multiple links: includes
    filter: {author: {has: {_entry: authorId}}},
    select: {title: Query.title, url: Query.url},
    orderBy: {desc: BlogPost.publishDate},
    skip: page * 10,
    take: 10
  })
}
